parameters.jsCode:
// The Supabase fetch returns 389 rows and n8n delivers them as 389 ITEMS, so
// $input.first().json is a single feedback row, not the array this assumed.
// Array.isArray() then failed and the node returned total_rows: 0 on every run
// since the workflow shipped. The 401 on the Anthropic node hid it: the run died
// one step later, so nobody saw the clusterer had already given up.
// Handles both shapes, since a PostgREST call can also arrive as one item whose
// json IS the array.
const all = $input.all().map(i => i.json);
const rows = (all.length === 1 && Array.isArray(all[0])) ? all[0] : all;
if (!Array.isArray(rows) || rows.length === 0) {
  return [{ json: { clusters: [], total_rows: 0, run_id: 'vera_' + Date.now().toString(36) } }];
}

const negative = rows.filter(r => (r.vote != null && r.vote < 0) || r.rejection_reason);
const groups = {};
for (const r of negative) {
  const key = [r.agent_id || r.original_agent || 'unknown', r.source_table || 'unknown', r.reason_code || 'other'].join('|');
  if (!groups[key]) groups[key] = [];
  groups[key].push(r);
}

// '_other' is the absence of a reason, not a reason. A brief edit written from
// "Krish rejected 59 leads for unspecified reasons" is invention: the model has
// nothing to generalise from and will confabulate a pattern to fill the gap.
// reject_reason_neighbors already excludes these codes for exactly this reason
// ("the absence of a reason can never be a prediction"); the clusterer did not,
// so the two halves of the loop disagreed about what counts as signal.
//
// They are counted, never silently dropped: a large unreasoned pile is itself
// the finding -- it says the chip list on that surface does not hold what Krish
// means, which is a taxonomy bug to fix rather than a brief to rewrite.
const isUnreasoned = (code) => code === 'other' || /_other$/.test(code);

const clusters = [];
const unreasoned = [];
for (const [key, items] of Object.entries(groups)) {
  const [agent_id, source_table, reason_code] = key.split('|');
  if (isUnreasoned(reason_code)) {
    if (items.length >= 2) unreasoned.push({ agent_id, source_table, reason_code, count: items.length });
    continue;
  }
  // Every surviving cluster now carries a real code, so the old two-tier
  // threshold collapses to one: two matches with a stated reason is a pattern.
  if (items.length < 2) continue;
  clusters.push({
    cluster_key: key,
    agent_id,
    source_table,
    reason_code,
    feedback_ids: items.map(i => i.id),
    sample_reason_texts: items.map(i => i.reason_text || i.feedback_text).filter(Boolean).slice(0, 8),
    sample_source_ids: items.map(i => i.source_id || i.original_item_id).filter(Boolean).slice(0, 8),
    count: items.length,
  });
}

unreasoned.sort((a, b) => b.count - a.count);

return [{ json: {
  clusters,
  total_rows: rows.length,
  negative_rows: negative.length,
  eligible_clusters: clusters.length,
  unreasoned_clusters: unreasoned.length,
  unreasoned_rows: unreasoned.reduce((n, u) => n + u.count, 0),
  unreasoned_top: unreasoned.slice(0, 8),
  run_id: 'vera_' + Date.now().toString(36),
} }];

parameters.jsonBody:
={{ { model: 'claude-sonnet-4-6', max_tokens: 4000, temperature: 0.2, system: "You are Vera, the mind/make OS reflection layer. You read clusters of negative feedback that landed on a specific agent's outputs and propose ONE concrete brief edit that would prevent the same mistake. Return ONLY JSON, no prose, no code fences. Shape: { "clusters": [ { "cluster_key":string, "correction_instruction":string, "proposed_brief_edit":string, "confidence":"low"|"medium"|"high" } ] }. Echo cluster_key back exactly as given: it is the join key. Do NOT output feedback ids or agent names; provenance is tracked upstream from cluster_key. correction_instruction is a one-line summary of the change. proposed_brief_edit is the exact prose to insert into the agent's brief, phrased as a positive rule (e.g., 'When extracting why_relevant, ground claims in specific signals from the source document; do not invent generic motivations.'). Skip clusters where feedback is inconsistent or noisy. No em dashes. Use commas, colons, parentheses, or line breaks.", messages: [{ role: 'user', content: 'Aggregated negative-feedback clusters from the last week:
' + JSON.stringify((($('Cluster').first().json || {}).clusters || []).map(c => ({ cluster_key: c.cluster_key, agent_id: c.agent_id, source_table: c.source_table, reason_code: c.reason_code, count: c.count, sample_reason_texts: c.sample_reason_texts, sample_source_ids: c.sample_source_ids }))) + '

Propose brief edits per the system prompt.' }] } }}

parameters.jsCode:
const item = $input.first().json;
let text = item.content?.[0]?.text || item.text || JSON.stringify(item);
text = text.trim();
if (text.startsWith('```')) {
  text = text.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
}

let parsed;
try { parsed = JSON.parse(text); }
catch (e) {
  return [{ json: { ok: false, rejection_reason: 'invalid_json', raw: text.slice(0,2000), error: String(e) }}];
}

// Provenance comes from the clusterer, never from the model. Asking Sonnet to
// echo back every feedback UUID got a SAMPLE: 50 ids for clusters that actually
// covered 191 rows, so 141 rows stayed unconsumed and re-clustered into the same
// corrections every Sunday. The clusterer already knows exact membership, so join
// on cluster_key and take ids, agent and reason code from it.
const byKey = new Map((($('Cluster').first().json || {}).clusters || []).map(c => [c.cluster_key, c]));

// corrections.confidence is double precision, not text. The model is asked for
// low|medium|high, so map it. 0.8 is the documented aggregation threshold
// (DATA-PIPELINE.md), so 'high' must land above it and 'medium' below.
const CONF = { low: 0.3, medium: 0.6, high: 0.9 };
const validConf = new Set(['low','medium','high']);
const clusters = Array.isArray(parsed.clusters) ? parsed.clusters : [];
const rows = [];
const unmatched = [];
for (const c of clusters) {
  if (!c || !c.proposed_brief_edit) continue;
  const src = byKey.get(c.cluster_key);
  // A cluster_key the clusterer never emitted is an invented grouping. Drop it:
  // a correction with no traceable evidence is worse than no correction.
  if (!src) { unmatched.push(c.cluster_key || '(none)'); continue; }
  rows.push({
    agent_id: src.agent_id,
    correction_type: 'pattern_recall',
    detection_source: 'vera_feedback_aggregation',
    pattern_reason_code: src.reason_code || null,
    consumed_feedback_ids: src.feedback_ids || [],
    correction_instruction: String(c.correction_instruction || '').slice(0, 2000),
    proposed_brief_edit: String(c.proposed_brief_edit || '').slice(0, 4000),
    confidence: CONF[validConf.has(c.confidence) ? c.confidence : 'low'],
    approval_state: 'pending',
    status: 'analyzed',
    detected_at: new Date().toISOString(),
  });
}
if (unmatched.length) console.log('dropped unmatched cluster_keys: ' + unmatched.join(', '));
return rows.map(r => ({ json: r }));

// Every correction that was written, not just the first one.
// This used $input.first().json. Write Corrections runs once per correction, so
// with 8 corrections inserted this node saw 8 items and fanned out only item[0]:
// 10 of the 50 claimed feedback ids were ever marked consumed, and the other 40
// rows stayed unconsumed and re-clustered into duplicate corrections next run.
const out = [];
for (const item of $input.all()) {
  const payload = item.json;
  // return=representation gives an array of inserted rows; tolerate a bare object.
  const rows = Array.isArray(payload) ? payload : [payload];
  for (const r of rows) {
    if (!r || !r.id || !Array.isArray(r.consumed_feedback_ids)) continue;
    for (const fid of r.consumed_feedback_ids) {
      out.push({ json: { correction_id: r.id, feedback_id: fid } });
    }
  }
}
return out;
